// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        address ownerBefore = c.owner();
        vm.assume(actor != ownerBefore);
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // must not happen for a non-owner
        } catch {
            // reference reverts for non-owner
        }
        assertTrue(c.owner() == ownerBefore);
    }
}
